class _FakeMediaRepository implements MediaRepository {
  Either<Failure, OcrResult> Function()? nextResult;

  /// Lets a test hold `recognizeText()` unresolved, to simulate leaving
  /// the Foto tab (via a tab switch) while OCR is still running — same
  /// gate convention `_FakePhotoPicker.cameraGate`/`_FakeAudioTranscriber.
  /// transcribeGate` above already use.
  Completer<void>? gate;

  @override
  Future<Either<Failure, OcrResult>> recognizeText({
    required Uint8List imageBytes,
    required String mimeType,
  }) async {
    // Stays loud by default (same convention `_FakePhotoPicker.
    // pickFromCamera()` above restores) — only spec-3-4's "Foto→Áudio
    // mid-OCR" test configures `gate`/`nextResult`; no other test in
    // this file ever lets a pick reach OCR.
    if (gate == null && nextResult == null) {
      throw UnimplementedError('not expected to be called');
    }
    final activeGate = gate;
    if (activeGate != null) {
      await activeGate.future;
    }
    return nextResult!();
  }
}

