testWidgets(
  'Story 3.4: Foto→Áudio switch mid-OCR discards the pending OCR '
  'result and starts recording immediately (the cross-tab rule '
  'exercised above only ever interrupted the picker call itself — '
  'here the picker has already resolved and OCR is the pending async '
  'op left to cancel)',
  (tester) async {
    fakePhotoPicker.nextCameraResult = PickedPhoto(
      path: photoFile.path,
      mimeType: 'image/png',
    );
    fakeMediaRepository.gate = Completer<void>();
    fakeMediaRepository.nextResult = () =>
        right(const OcrResult(text: 'nunca deveria aparecer', confidence: 'high'));
    await _openModal(
      tester,
      cubit: textCubit,
      audioCubit: audioCubit,
      photoCubit: photoCubit,
    );
    await tester.pumpAndSettle();

    await tester.tap(find.text('Foto'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Câmera'));
    await tester.pumpAndSettle();

    // The picker resolved and OCR is now in flight, held by the gate.
    expect(photoCubit.state, isA<PhotoProcessing>());
    expect(fakeRepository.createCallCount, 0);

    await tester.tap(find.text('Áudio'));
    await tester.pump();

    // Recording starts immediately despite the still-pending OCR.
    expect(fakeMicRecorder.startCalls, 1);
    expect(photoCubit.state, isA<PhotoIdle>());
    expect(fakeRepository.createCallCount, 0);

    // The stale OCR result never resurrects the Foto tab's own state.
    fakeMediaRepository.gate!.complete();
    await tester.pump();

    expect(photoCubit.state, isA<PhotoIdle>());
    expect(fakeRepository.createCallCount, 0);

